def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Final round is always a dominant defection.
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_c = 0
    my_c = 0
    my_d = 0
    for i in range(n):
        a = history[i][0]
        b = history[i][1]
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1
        else:
            my_d += 1

    # Recent 8-round statistics: used to start a low-cost probe only after a long clean mutual-cooperation block.
    rl = n if n < 8 else 8
    recent_opp_c = 0
    recent_my_c = 0
    for i in range(n - rl, n):
        a = history[i][0]
        b = history[i][1]
        if b == 'C':
            recent_opp_c += 1
        if a == 'C':
            recent_my_c += 1

    # Recent 12-round statistics: smoother view for forgiveness/punishment.
    r12 = n if n < 12 else 12
    recent_opp_c12 = 0
    for i in range(n - r12, n):
        if history[i][1] == 'C':
            recent_opp_c12 += 1

    # Streaks.
    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    my_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C':
            my_c_streak += 1
        else:
            break

    # punished: opponent defected after our previous defection.
    # unprovoked: opponent defected after our previous cooperation.
    punished = 0
    unprovoked = 0
    for i in range(1, n):
        prev_my = history[i - 1][0]
        curr_opp = history[i][1]
        if prev_my == 'D' and curr_opp == 'D':
            punished += 1
        elif prev_my == 'C' and curr_opp == 'D':
            unprovoked += 1

    forgiving = True
    if my_d > 0:
        forgiving = (my_d - punished) * 10 >= my_d * 7

    # A very conservative "exploitable" classifier.
    # If we defect once against an overwhelmingly cooperative opponent and then
    # they cooperate when given the chance to punish, switch to exploitation.
    forgive_test = False
    if (
        n >= 13
        and my_d == 1
        and punished == 0
        and last_my == 'C'
        and last_opp == 'C'
        and history[-2][0] == 'D'
        and history[-2][1] == 'C'
        and opp_c * 10 >= n * 9
        and unprovoked <= 1
    ):
        forgive_test = True

    exploitable = forgive_test
    if (
        n >= 10
        and my_d >= 2
        and forgiving
        and opp_c * 10 >= n * 7
        and recent_opp_c12 >= 5
        and unprovoked <= 2
    ):
        exploitable = True

    # If the opponent is mostly hostile, stop trying to cooperate.
    hostile = False
    if opp_c * 10 < n * 2:
        hostile = True
    if opp_c <= 2 and n >= 8:
        hostile = True
    if recent_opp_c12 <= 1 and n >= 12:
        hostile = True
    if opp_d_streak >= 6:
        hostile = True
    if unprovoked >= 10 and n >= 20:
        hostile = True

    if hostile:
        return 'D'

    # Once classified as exploitable, take the 5-point payoff while the opponent cooperates.
    if exploitable:
        if last_opp == 'C':
            return 'D'

        # If they defect, do not blindly continue.
        if last_my == 'D':
            return 'C'

        # Provoked punishment: try to reset.
        if n >= 2 and history[-2][0] == 'D' and opp_d_streak <= 3:
            return 'C'

        # Persistent mutual defection: stay defensive.
        if opp_d_streak >= 4 and my_c_streak >= 2:
            return 'D'

        # If there are unprovoked defections but they are still mostly cooperative,
        # punish briefly rather than continue exploitation.
        if unprovoked >= 2 and opp_c * 10 >= n * 8:
            return 'D'

        return 'C'

    # Default policy: generous retaliatory Tit-for-Tat with quick recovery.
    if last_opp == 'D':
        if last_my == 'D':
            # Mutual defection: try to break the cycle unless the opponent seems hostile.
            if opp_c >= 5 and recent_opp_c12 >= 3 and opp_d_streak <= 4:
                return 'C'
            return 'D'

        if n >= 2 and history[-2][0] == 'D':
            # Their defection is likely a response to our recent defection.
            # Forgive unless they keep defecting while we are cooperative.
            if opp_d_streak >= 4 and my_c_streak >= 2:
                return 'D'
            if opp_c >= 5 or recent_opp_c12 >= 3:
                return 'C'
            return 'D'

        # Unprovoked opponent defection: punish.
        return 'D'

    # Opponent cooperated last round.
    if last_my == 'D':
        # We defected and they cooperated. By default return cooperation to reset,
        # unless the exploitable classifier already says to keep defecting.
        return 'C'

    # Both cooperated last round. Make at most one careful probe after a long clean history.
    if (
        n >= 12
        and my_d == 0
        and recent_opp_c == rl
        and recent_my_c == rl
        and opp_c * 10 >= n * 9
        and unprovoked <= 1
    ):
        return 'D'

    return 'C'
